import XCTest
@testable import RNSOverMeshCore
import ReticulumSwift

/// Byte-for-byte wire-compatibility proof: the Swift fragmenters must emit the
/// exact strings the upstream Python interfaces produce. The `python*` fixtures
/// below were generated by running the *actual* fragmentation code from
/// `comms-engineer/RNS_Over_Meshcore` (Dynamic `_PacketHandler`, Channel
/// `_PacketHandler`, Contact `PacketHandler.split_data`) over deterministic inputs.
/// If these pass, a Swift node and a Python node agree on the wire.
final class MeshCoreWireParityTests: XCTestCase {

    // Deterministic inputs matching the fixture generator.
    private var dynamicData: Data { Data((0 ..< 200).map { UInt8(($0 * 7) & 0xff) }) }
    private var channelData: Data { Data((0 ..< 150).map { UInt8(($0 * 3) & 0xff) }) }
    private var contactData: Data { Data((0 ..< 300).map { UInt8(($0 * 5) & 0xff) }) }

    private let pythonDynamic = [
        "RNS:AN6tvu8EAAcOFRwjKjE4P0ZNVFtiaXB3foWMk5qhqK-2vcTL0tng5-71_AMKERgfJi00O0JJUFdeZWxzeoGIj5adpKuyuQ",
        "RNS:Ad6tvu8EwMfO1dzj6vH4_wYNFBsiKTA3PkVMU1phaG92fYSLkpmgp661vMPK0djf5u30-wIJEBceJSwzOkFIT1ZdZGtyeQ",
        "RNS:At6tvu8EgIeOlZyjqrG4v8bN1Nvi6fD3_gUMExohKC82PURLUllgZ251fIOKkZifpq20u8LJ0Nfe5ezz-gEIDxYdJCsyOQ",
        "RNS:A96tvu8EQEdOVVxjanE",
    ]

    private let pythonChannel = [
        "RNS:Uk4A3q2-7wcDAAMGCQwPEhUYGx4hJCcqLTAzNjk8P0JFSEtOUVRXWl1gY2ZpbG9ydXh7foGEh4qNkJOWmZyfoqWoq66xtLe6vQ",
        "RNS:Uk4B3q2-7wcDwMPGyczP0tXY297h5Ofq7fDz9vn8_wIFCAsOERQXGh0gIyYpLC8yNTg7PkFER0pNUFNWWVxfYmVoa25xdHd6fQ",
        "RNS:Uk4C3q2-7wcDgIOGiYyPkpWYm56hpKeqrbCztrm8vw",
    ]

    private let pythonContact = [
        "KgEABQoPFBkeIygtMjc8QUZLUFVaX2RpbnN4fYKHjJGWm6Clqq+0ub7DyM3S19zh5uvw9fr/BAkOExgdIicsMTY7QEVKT1RZXmNobXJ3fIGGi5CVmp+kqa6zuL3Cx8zR1tvg5erv9Pn+AwgNEhccISYrMDU6P0RJTlNYXWJnbHF2e4CFio+UmZ6jqK2yt7zBxsvQ1drf5Onu",
        "Kv7z+P0CBwwRFhsgJSovNDk+Q0hNUldcYWZrcHV6f4SJjpOYnaKnrLG2u8DFys/U2d7j6O3y9/wBBgsQFRofJCkuMzg9QkdMUVZbYGVqb3R5foOIjZKXnKGmq7C1ur/Eyc7T2N3i5+zx9vsABQoPFBkeIygtMjc8QUZLUFVaX2RpbnN4fYKHjJGWm6Clqq+0ub7DyM3S1w==",
    ]

    func testDynamicFragmenterMatchesPython() {
        XCTAssertEqual(DynamicFragmenter.fragments(dynamicData, packetID: 0xDEADBEEF, payloadSize: 64),
                       pythonDynamic)
    }

    func testChannelFragmenterMatchesPython() {
        XCTAssertEqual(ChannelFragmenter.fragments(channelData, sourceID: Data([0xDE, 0xAD, 0xBE, 0xEF]),
                                                   packetID: 7, payloadSize: 64),
                       pythonChannel)
    }

    func testContactFragmenterMatchesPython() {
        XCTAssertEqual(ContactFragmenter.fragments(contactData, index: 42, maxPayload: 160),
                       pythonContact)
    }

    // MARK: - Swift ↔ Swift Dynamic loopback

    /// Two independent Dynamic interfaces bridged by an in-memory shared "channel":
    /// a packet fragmented + broadcast by A must reassemble intact at B, proving the
    /// full send → fragment → channel → reassemble → deliver path is self-consistent.
    func testDynamicLoopbackAcrossTwoInterfaces() async throws {
        var cfg = MeshCoreDynamicConfig()
        cfg.channelSecretHex = "c4d2b6c8254e3b11200f57e95dcb1197"
        cfg.fragmentDelay = 0; cfg.announceRetransmitExtra = 0; cfg.announceRate = 0
        cfg.discoverySettleDelay = 999; cfg.bindHeartbeat = 999; cfg.cleanupInterval = 999

        let a = MockMeshCoreCompanion(); a.startInfo.name = "NodeA"; a.startInfo.publicKey = String(repeating: "aa", count: 32)
        let b = MockMeshCoreCompanion(); b.startInfo.name = "NodeB"; b.startInfo.publicKey = String(repeating: "bb", count: 32)
        // Shared channel: A's broadcasts reach B (prefixed with A's node name) and vice versa.
        a.channelSendHook = { _, text in b.deliverChannel(text: "NodeA: \(text)") }
        b.channelSendHook = { _, text in a.deliverChannel(text: "NodeB: \(text)") }

        let ifaceA = MeshCoreDynamicInterface(companion: a, config: cfg)
        let ifaceB = MeshCoreDynamicInterface(companion: b, config: cfg)
        let received = LoopbackBox()
        ifaceB.rawInboundHandler = { data, _ in received.append(data) }
        try await ifaceA.bringUp()
        try await ifaceB.bringUp()

        let packet = Packet(destinationType: .single, packetType: .announce,
                            destinationHash: Data(repeating: 0xA7, count: 16),
                            data: Data(String(repeating: "loopback ", count: 20).utf8))
        let wire = try packet.pack()
        try ifaceA.send(packet)

        for _ in 0 ..< 300 {
            if received.values.first == wire { break }
            try await Task.sleep(nanoseconds: 5_000_000)
        }
        XCTAssertEqual(received.values.first, wire)
        ifaceA.stop(); ifaceB.stop()
    }
}

private final class LoopbackBox: @unchecked Sendable {
    private let lock = NSLock()
    private var _values: [Data] = []
    var values: [Data] { lock.lock(); defer { lock.unlock() }; return _values }
    func append(_ d: Data) { lock.lock(); _values.append(d); lock.unlock() }
}
